INSERT IGNORE INTO `clinical_notes` (`id`, `hospital_id`, `patient_id`, `encounter_id`, `author_id`, `note_number`, `note_type`, `title`, `subjective`, `objective`, `assessment`, `plan`, `narrative`, `tags`, `is_signed`, `signed_at`, `signed_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 2, 1, 1, 2, 'NOTE-2026-000001', 'Progress', 'Day 1 progress note', 'Patient complains of fever (3 days), headache, body pains. No vomiting, no diarrhoea.', 'T 38.4°C, BP 120/80, HR 88, RR 18, SpO2 98%. General examination: acutely ill-looking, no pallor, no jaundice.', 'Suspected malaria. Differential: typhoid fever, URTI.', 'Send MP+RDT, FBC. Start artemether/lumefantrine. Paracetamol for fever. Review in 48 hours.', NULL, NULL, 1, '2026-09-28 17:04:58', 2, '2026-09-29 00:04:58', '2026-09-29 00:04:58', NULL),
